def main():
    keys = json.load(open(KEYS, encoding="utf-8"))
    rows, miss = [], []
    for i, k in enumerate(keys, 1):
        v = T.get(i)
        if v is None:
            miss.append((i, k)); continue
        if v == "":
            continue                      # 显式跳过（元数据）
        assert "\t" not in v and "\n" not in v, f"第 {i} 条含制表符/换行"
        rows.append((k, v))
    with open(OUT, "a", encoding="utf-8", newline="\n") as f:
        for k, v in rows:
            f.write(k + "\t" + v + "\n")
    print(f"追加 {len(rows)} 条 → {OUT}")
    print(f"未译 {len(miss)} 条：")
    for i, k in miss:
        print(f"  {i:3d} {k[:70]}")


if __name__ == "__main__":
    main()
